CREATE TABLE public.learning_modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_modules TO authenticated; GRANT ALL ON public.learning_modules TO service_role; REVOKE ALL ON public.learning_modules FROM anon; ALTER TABLE public.learning_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_modules_read ON public.learning_modules FOR SELECT TO authenticated USING(status='approved' OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.learning_topics(id text PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 100), module_id uuid NOT NULL REFERENCES public.learning_modules(id), title text NOT NULL, position integer NOT NULL CHECK(position>0), prerequisite text REFERENCES public.learning_topics(id), estimated_minutes integer NOT NULL DEFAULT 45 CHECK(estimated_minutes BETWEEN 1 AND 600), UNIQUE(module_id,position));
GRANT SELECT ON public.learning_topics TO authenticated; GRANT ALL ON public.learning_topics TO service_role; REVOKE ALL ON public.learning_topics FROM anon; ALTER TABLE public.learning_topics ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_topics_read ON public.learning_topics FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.learning_modules m WHERE m.id=module_id AND (m.status='approved' OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.learning_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id text NOT NULL REFERENCES public.learning_topics(id), version integer NOT NULL DEFAULT 1, content jsonb NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), reviewed_by uuid, reviewed_at timestamptz, UNIQUE(topic_id,version));
GRANT SELECT ON public.learning_notes TO authenticated; GRANT ALL ON public.learning_notes TO service_role; REVOKE ALL ON public.learning_notes FROM anon; ALTER TABLE public.learning_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_notes_read ON public.learning_notes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (status='approved' AND EXISTS(SELECT 1 FROM public.learning_topics t JOIN public.learning_modules m ON m.id=t.module_id WHERE t.id=topic_id AND m.status='approved')));
CREATE TABLE public.topic_quiz_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id text NOT NULL REFERENCES public.learning_topics(id), version integer NOT NULL DEFAULT 1, prompt text NOT NULL CHECK(length(prompt) BETWEEN 1 AND 1000), options jsonb NOT NULL CHECK(jsonb_typeof(options)='array' AND jsonb_array_length(options)=4), correct_option integer NOT NULL CHECK(correct_option BETWEEN 0 AND 3), explanation text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')));
GRANT ALL ON public.topic_quiz_questions TO service_role; REVOKE ALL ON public.topic_quiz_questions FROM anon,authenticated; ALTER TABLE public.topic_quiz_questions ENABLE ROW LEVEL SECURITY;
CREATE INDEX topic_bank_lookup ON public.topic_quiz_questions(topic_id,status);
CREATE TABLE public.ai_roadmaps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, module_id uuid NOT NULL REFERENCES public.learning_modules(id), preferences jsonb NOT NULL, topic_ids jsonb NOT NULL CHECK(jsonb_typeof(topic_ids)='array'), guidance text NOT NULL DEFAULT '', model text NOT NULL, catalog_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_roadmaps TO authenticated; GRANT ALL ON public.ai_roadmaps TO service_role; REVOKE ALL ON public.ai_roadmaps FROM anon; ALTER TABLE public.ai_roadmaps ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_plan_read ON public.ai_roadmaps FOR SELECT TO authenticated USING(public.can_read_learning(user_id));
CREATE INDEX curriculum_owner_plans ON public.ai_roadmaps(user_id,created_at DESC);
CREATE TABLE public.roadmap_milestones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), roadmap_id uuid NOT NULL REFERENCES public.ai_roadmaps(id) ON DELETE CASCADE, week integer NOT NULL CHECK(week BETWEEN 1 AND 52), topic_ids jsonb NOT NULL, exercise text NOT NULL DEFAULT '');
GRANT SELECT ON public.roadmap_milestones TO authenticated; GRANT ALL ON public.roadmap_milestones TO service_role; REVOKE ALL ON public.roadmap_milestones FROM anon; ALTER TABLE public.roadmap_milestones ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_milestones_read ON public.roadmap_milestones FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.ai_roadmaps r WHERE r.id=roadmap_id AND public.can_read_learning(r.user_id)));
CREATE TABLE public.student_quiz_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, topic_id text NOT NULL REFERENCES public.learning_topics(id), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','finalized')), started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, marks integer CHECK(marks BETWEEN 0 AND 5), percentage integer CHECK(percentage BETWEEN 0 AND 100), passed boolean, UNIQUE(id,user_id));
GRANT SELECT ON public.student_quiz_attempts TO authenticated; GRANT ALL ON public.student_quiz_attempts TO service_role; REVOKE ALL ON public.student_quiz_attempts FROM anon; ALTER TABLE public.student_quiz_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_attempt_read ON public.student_quiz_attempts FOR SELECT TO authenticated USING(public.can_read_learning(user_id));
CREATE UNIQUE INDEX curriculum_one_active_attempt ON public.student_quiz_attempts(user_id,topic_id) WHERE status='active';
CREATE INDEX curriculum_attempt_owner ON public.student_quiz_attempts(user_id,topic_id,started_at DESC);
CREATE TABLE public.student_quiz_answers(attempt_id uuid NOT NULL REFERENCES public.student_quiz_attempts(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.topic_quiz_questions(id), position integer NOT NULL CHECK(position BETWEEN 1 AND 5), selected_option integer CHECK(selected_option BETWEEN 0 AND 3), PRIMARY KEY(attempt_id,question_id), UNIQUE(attempt_id,position));
GRANT SELECT ON public.student_quiz_answers TO authenticated; GRANT ALL ON public.student_quiz_answers TO service_role; REVOKE ALL ON public.student_quiz_answers FROM anon; ALTER TABLE public.student_quiz_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_answer_read ON public.student_quiz_answers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.student_quiz_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid()));
CREATE TABLE public.student_topic_progress(user_id uuid NOT NULL, topic_id text NOT NULL REFERENCES public.learning_topics(id), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, passed_attempt uuid, PRIMARY KEY(user_id,topic_id), FOREIGN KEY(passed_attempt,user_id) REFERENCES public.student_quiz_attempts(id,user_id));
GRANT SELECT ON public.student_topic_progress TO authenticated; GRANT ALL ON public.student_topic_progress TO service_role; REVOKE ALL ON public.student_topic_progress FROM anon; ALTER TABLE public.student_topic_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_progress_read ON public.student_topic_progress FOR SELECT TO authenticated USING(public.can_read_learning(user_id));
CREATE TABLE public.student_learning_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, topic_id text NOT NULL REFERENCES public.learning_topics(id), last_event uuid, last_at timestamptz NOT NULL DEFAULT now(), active_seconds integer NOT NULL DEFAULT 0 CHECK(active_seconds>=0), UNIQUE(user_id,topic_id));
GRANT SELECT ON public.student_learning_sessions TO authenticated; GRANT ALL ON public.student_learning_sessions TO service_role; REVOKE ALL ON public.student_learning_sessions FROM anon; ALTER TABLE public.student_learning_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_time_read ON public.student_learning_sessions FOR SELECT TO authenticated USING(public.can_read_learning(user_id));
CREATE TABLE public.learning_ai_limits(user_id uuid PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 0);
GRANT ALL ON public.learning_ai_limits TO service_role; REVOKE ALL ON public.learning_ai_limits FROM anon,authenticated; ALTER TABLE public.learning_ai_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.curriculum_topic_allowed(p_topic text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.learning_topics t JOIN public.learning_modules m ON m.id=t.module_id WHERE t.id=p_topic AND m.status='approved' AND (t.prerequisite IS NULL OR EXISTS(SELECT 1 FROM public.student_topic_progress p WHERE p.user_id=auth.uid() AND p.topic_id=t.prerequisite AND p.completed_at IS NOT NULL))) $$;
REVOKE ALL ON FUNCTION public.curriculum_topic_allowed(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_topic_allowed(text) TO authenticated,service_role;
CREATE FUNCTION public.curriculum_snapshot(p_user uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=coalesce(p_user,auth.uid()); BEGIN IF auth.uid() IS NULL OR NOT public.can_read_learning(u) THEN RAISE EXCEPTION 'Forbidden'; END IF;
RETURN jsonb_build_object('modules',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at) FROM public.learning_modules m WHERE m.status='approved'),'[]'::jsonb),'topics',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.position) FROM public.learning_topics t JOIN public.learning_modules m ON m.id=t.module_id WHERE m.status='approved'),'[]'::jsonb),'progress',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.student_topic_progress p WHERE p.user_id=u),'[]'::jsonb),'attempts',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.started_at DESC) FROM public.student_quiz_attempts a WHERE a.user_id=u),'[]'::jsonb),'plans',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC) FROM public.ai_roadmaps r WHERE r.user_id=u),'[]'::jsonb),'milestones',coalesce((SELECT jsonb_agg(to_jsonb(k) ORDER BY k.week) FROM public.roadmap_milestones k JOIN public.ai_roadmaps r ON r.id=k.roadmap_id WHERE r.user_id=u),'[]'::jsonb),'sessions',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.student_learning_sessions s WHERE s.user_id=u),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.curriculum_snapshot(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_snapshot(uuid) TO authenticated,service_role;
CREATE FUNCTION public.curriculum_topic(p_topic text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_topic IS NULL OR NOT public.curriculum_topic_allowed(p_topic) THEN RAISE EXCEPTION 'Complete prerequisite or course is not approved'; END IF;
INSERT INTO public.student_topic_progress(user_id,topic_id) VALUES(auth.uid(),p_topic) ON CONFLICT DO NOTHING;
RETURN jsonb_build_object('topic',(SELECT to_jsonb(t) FROM public.learning_topics t WHERE t.id=p_topic),'notes',(SELECT n.content FROM public.learning_notes n WHERE n.topic_id=p_topic AND n.status='approved' ORDER BY n.version DESC LIMIT 1)); END $$;
REVOKE ALL ON FUNCTION public.curriculum_topic(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_topic(text) TO authenticated,service_role;
CREATE FUNCTION public.topic_quiz_snapshot(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.student_quiz_attempts; BEGIN SELECT * INTO a FROM public.student_quiz_attempts WHERE id=p_attempt AND user_id=auth.uid(); IF auth.uid() IS NULL OR a.id IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF;
RETURN jsonb_build_object('attempt',to_jsonb(a),'questions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',q.id,'prompt',q.prompt,'options',q.options,'selected_option',b.selected_option,'position',b.position) || CASE WHEN a.status='finalized' THEN jsonb_build_object('correct_option',q.correct_option,'explanation',q.explanation) ELSE '{}'::jsonb END ORDER BY b.position) FROM public.student_quiz_answers b JOIN public.topic_quiz_questions q ON q.id=b.question_id WHERE b.attempt_id=a.id),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.topic_quiz_snapshot(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.topic_quiz_snapshot(uuid) TO authenticated,service_role;
CREATE FUNCTION public.topic_quiz_start(p_topic text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid; BEGIN IF p_topic IS NULL OR NOT public.curriculum_topic_allowed(p_topic) THEN RAISE EXCEPTION 'Locked topic'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_topic,0)); SELECT id INTO a FROM public.student_quiz_attempts WHERE user_id=auth.uid() AND topic_id=p_topic AND status='active';
IF a IS NULL THEN IF (SELECT count(*) FROM public.topic_quiz_questions WHERE topic_id=p_topic AND status='approved')<5 THEN RAISE EXCEPTION 'Question bank not approved'; END IF;
INSERT INTO public.student_quiz_attempts(user_id,topic_id) VALUES(auth.uid(),p_topic) RETURNING id INTO a;
INSERT INTO public.student_quiz_answers(attempt_id,question_id,position) SELECT a,q.id,row_number() OVER() FROM (SELECT id FROM public.topic_quiz_questions WHERE topic_id=p_topic AND status='approved' ORDER BY random() LIMIT 5) q;
END IF; RETURN public.topic_quiz_snapshot(a); END $$;
REVOKE ALL ON FUNCTION public.topic_quiz_start(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.topic_quiz_start(text) TO authenticated,service_role;
CREATE FUNCTION public.topic_quiz_save(p_attempt uuid,p_question uuid,p_option integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.student_quiz_attempts; BEGIN IF auth.uid() IS NULL OR p_attempt IS NULL OR p_question IS NULL OR p_option IS NULL OR p_option NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'Invalid answer'; END IF;
SELECT * INTO a FROM public.student_quiz_attempts WHERE id=p_attempt AND user_id=auth.uid() FOR UPDATE; IF a.id IS NULL OR a.status<>'active' THEN RAISE EXCEPTION 'Invalid attempt'; END IF;
UPDATE public.student_quiz_answers SET selected_option=p_option WHERE attempt_id=a.id AND question_id=p_question; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid question'; END IF; RETURN public.topic_quiz_snapshot(a.id); END $$;
REVOKE ALL ON FUNCTION public.topic_quiz_save(uuid,uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.topic_quiz_save(uuid,uuid,integer) TO authenticated,service_role;
CREATE FUNCTION public.topic_quiz_submit(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.student_quiz_attempts; n integer; BEGIN SELECT * INTO a FROM public.student_quiz_attempts WHERE id=p_attempt AND user_id=auth.uid() FOR UPDATE; IF auth.uid() IS NULL OR a.id IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF a.status='finalized' THEN RETURN public.topic_quiz_snapshot(a.id); END IF;
IF (SELECT count(*) FROM public.student_quiz_answers WHERE attempt_id=a.id AND selected_option IS NOT NULL)<>5 THEN RAISE EXCEPTION 'Answer all five questions'; END IF;
SELECT count(*) INTO n FROM public.student_quiz_answers b JOIN public.topic_quiz_questions q ON q.id=b.question_id WHERE b.attempt_id=a.id AND b.selected_option=q.correct_option;
UPDATE public.student_quiz_attempts SET status='finalized',submitted_at=now(),marks=n,percentage=n*20,passed=n>=4 WHERE id=a.id;
IF n>=4 THEN INSERT INTO public.student_topic_progress(user_id,topic_id,completed_at,passed_attempt) VALUES(auth.uid(),a.topic_id,now(),a.id) ON CONFLICT(user_id,topic_id) DO UPDATE SET completed_at=coalesce(student_topic_progress.completed_at,excluded.completed_at),passed_attempt=coalesce(student_topic_progress.passed_attempt,excluded.passed_attempt); END IF;
RETURN public.topic_quiz_snapshot(a.id); END $$;
REVOKE ALL ON FUNCTION public.topic_quiz_submit(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.topic_quiz_submit(uuid) TO authenticated,service_role;
CREATE FUNCTION public.topic_activity_record(p_topic text,p_event uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.student_learning_sessions; elapsed integer; BEGIN IF p_event IS NULL OR NOT public.curriculum_topic_allowed(p_topic) THEN RAISE EXCEPTION 'Forbidden'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'time',0));
INSERT INTO public.student_learning_sessions(user_id,topic_id) VALUES(auth.uid(),p_topic) ON CONFLICT DO NOTHING; SELECT * INTO s FROM public.student_learning_sessions WHERE user_id=auth.uid() AND topic_id=p_topic FOR UPDATE;
IF s.last_event=p_event THEN RETURN s.active_seconds; END IF;
SELECT greatest(0,floor(extract(epoch FROM now()-max(last_at))))::integer INTO elapsed FROM public.student_learning_sessions WHERE user_id=auth.uid();
UPDATE public.student_learning_sessions SET last_event=p_event,last_at=now(),active_seconds=active_seconds+CASE WHEN elapsed BETWEEN 5 AND 40 THEN elapsed ELSE 0 END WHERE id=s.id RETURNING active_seconds INTO elapsed; RETURN elapsed; END $$;
REVOKE ALL ON FUNCTION public.topic_activity_record(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.topic_activity_record(text,uuid) TO authenticated,service_role;
CREATE FUNCTION public.learning_plan_reserve() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.learning_ai_limits; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.learning_ai_limits(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; SELECT * INTO r FROM public.learning_ai_limits WHERE user_id=auth.uid() FOR UPDATE; IF r.window_start<now()-interval '1 hour' THEN UPDATE public.learning_ai_limits SET window_start=now(),requests=1 WHERE user_id=auth.uid(); ELSIF r.requests>=10 THEN RAISE EXCEPTION 'Try again later'; ELSE UPDATE public.learning_ai_limits SET requests=requests+1 WHERE user_id=auth.uid(); END IF; END $$;
REVOKE ALL ON FUNCTION public.learning_plan_reserve() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.learning_plan_reserve() TO authenticated,service_role;
CREATE FUNCTION public.learning_plan_save(p_module uuid,p_preferences jsonb,p_topics jsonb,p_milestones jsonb,p_guidance text,p_model text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.learning_modules; r uuid; k jsonb; supplied text[]; canonical text[]; BEGIN IF auth.uid() IS NULL OR p_module IS NULL OR jsonb_typeof(p_topics) IS DISTINCT FROM 'array' OR jsonb_typeof(p_milestones) IS DISTINCT FROM 'array' OR jsonb_typeof(p_preferences) IS DISTINCT FROM 'object' OR length(p_guidance)>4000 OR p_model NOT IN ('google/gemini-4-argon','approved-standard-sequence') THEN RAISE EXCEPTION 'Invalid plan'; END IF; SELECT * INTO m FROM public.learning_modules WHERE id=p_module AND status='approved'; IF m.id IS NULL THEN RAISE EXCEPTION 'Unapproved course'; END IF;
SELECT array_agg(t.id ORDER BY t.position) INTO canonical FROM public.learning_topics t WHERE t.module_id=m.id AND NOT EXISTS(SELECT 1 FROM public.student_topic_progress p WHERE p.user_id=auth.uid() AND p.topic_id=t.id AND p.completed_at IS NOT NULL);
SELECT array_agg(v ORDER BY ord) INTO supplied FROM jsonb_array_elements_text(p_topics) WITH ORDINALITY AS x(v,ord); IF supplied IS DISTINCT FROM canonical THEN RAISE EXCEPTION 'Invalid topic selection or prerequisite order'; END IF;
INSERT INTO public.ai_roadmaps(user_id,module_id,preferences,topic_ids,guidance,model,catalog_version) VALUES(auth.uid(),m.id,p_preferences,p_topics,coalesce(p_guidance,''),p_model,m.version) RETURNING id INTO r;
FOR k IN SELECT value FROM jsonb_array_elements(p_milestones) LOOP IF (k->>'week')::integer NOT BETWEEN 1 AND 52 OR jsonb_typeof(k->'topic_ids') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(k->'topic_ids') x WHERE NOT (x.value=ANY(coalesce(canonical,ARRAY[]::text[])))) THEN RAISE EXCEPTION 'Invalid milestone'; END IF; INSERT INTO public.roadmap_milestones(roadmap_id,week,topic_ids,exercise) VALUES(r,(k->>'week')::integer,k->'topic_ids',left(coalesce(k->>'exercise',''),2000)); END LOOP; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.learning_plan_save(uuid,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.learning_plan_save(uuid,jsonb,jsonb,jsonb,text,text) TO authenticated,service_role;
CREATE FUNCTION public.curriculum_admin_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN jsonb_build_object('modules',coalesce((SELECT jsonb_agg(to_jsonb(m)) FROM public.learning_modules m),'[]'::jsonb),'topics',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.position) FROM public.learning_topics t),'[]'::jsonb),'notes',coalesce((SELECT jsonb_agg(to_jsonb(n)) FROM public.learning_notes n),'[]'::jsonb),'questions',coalesce((SELECT jsonb_agg(to_jsonb(q)) FROM public.topic_quiz_questions q),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.curriculum_admin_snapshot() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_admin_snapshot() TO authenticated,service_role;
CREATE FUNCTION public.curriculum_admin_save(p_module uuid,p_title text,p_topic text,p_notes jsonb,p_questions jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.learning_modules; q jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO m FROM public.learning_modules WHERE id=p_module FOR UPDATE; IF m.id IS NULL OR m.status<>'draft' THEN RAISE EXCEPTION 'Only draft curriculum can be edited'; END IF;
IF p_topic IS NULL THEN UPDATE public.learning_modules SET title=p_title WHERE id=m.id; RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM public.learning_topics WHERE id=p_topic AND module_id=m.id) OR jsonb_typeof(p_notes) IS DISTINCT FROM 'object' OR jsonb_typeof(p_questions) IS DISTINCT FROM 'array' OR jsonb_array_length(p_questions)<5 THEN RAISE EXCEPTION 'Invalid draft'; END IF;
UPDATE public.learning_topics SET title=p_title WHERE id=p_topic;
INSERT INTO public.learning_notes(topic_id,content) VALUES(p_topic,p_notes) ON CONFLICT(topic_id,version) DO UPDATE SET content=excluded.content WHERE learning_notes.status='draft';
DELETE FROM public.topic_quiz_questions WHERE topic_id=p_topic AND status='draft'; FOR q IN SELECT value FROM jsonb_array_elements(p_questions) LOOP INSERT INTO public.topic_quiz_questions(topic_id,prompt,options,correct_option,explanation) VALUES(p_topic,q->>'prompt',q->'options',(q->>'correct_option')::integer,q->>'explanation'); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.curriculum_admin_save(uuid,text,text,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_admin_save(uuid,text,text,jsonb,jsonb) TO authenticated,service_role;
CREATE FUNCTION public.curriculum_admin_approve(p_module uuid,p_attested boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.learning_modules; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR p_attested IS DISTINCT FROM true THEN RAISE EXCEPTION 'Admin review required'; END IF; SELECT * INTO m FROM public.learning_modules WHERE id=p_module FOR UPDATE; IF m.id IS NULL OR m.status<>'draft' THEN RAISE EXCEPTION 'Invalid course'; END IF;
IF (SELECT count(*) FROM public.learning_topics WHERE module_id=m.id)<10 OR EXISTS(SELECT 1 FROM public.learning_topics t WHERE t.module_id=m.id AND ((SELECT count(*) FROM public.topic_quiz_questions q WHERE q.topic_id=t.id AND q.status='draft')<5 OR NOT EXISTS(SELECT 1 FROM public.learning_notes n WHERE n.topic_id=t.id AND n.status='draft'))) THEN RAISE EXCEPTION 'Complete notes and five questions for ten topics required'; END IF;
UPDATE public.learning_modules SET status='approved',reviewed_by=auth.uid(),reviewed_at=now() WHERE id=m.id;
UPDATE public.learning_notes SET status='approved',reviewed_by=auth.uid(),reviewed_at=now() WHERE topic_id IN (SELECT id FROM public.learning_topics WHERE module_id=m.id);
UPDATE public.topic_quiz_questions SET status='approved' WHERE topic_id IN (SELECT id FROM public.learning_topics WHERE module_id=m.id); END $$;
REVOKE ALL ON FUNCTION public.curriculum_admin_approve(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_admin_approve(uuid,boolean) TO authenticated,service_role;